) WHEN 0 THEN NULL ELSE @UserData01 END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('UserData02'), @sync_supported_columns_tblMovementHistory)) WHEN 0 THEN NULL ELSE @UserData02 END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('UserData03'), @sync_supported_columns_tblMovementHistory)) WHEN 0 THEN NULL ELSE @UserData03 END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('UserData04'), @sync_supported_columns_tblMovementHistory)) WHEN 0 THEN NULL ELSE @UserData04 END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('UserData05'), @sync_supported_columns_tblMovementHistory)) WHEN 0 THEN NULL ELSE @UserData05 END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('UserData06'), @sync_supported_columns_tblMovementHistory)) WHEN 0 THEN NULL ELSE @UserData06 END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('UserData07'), @sync_supported_columns_tblMovementHistory)) WHEN 0 THEN NULL ELSE @UserData07 END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('UserData08'), @sync_supported_columns_tblMovementHistory)) WHEN 0 THEN NULL ELSE @UserData08 END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('UserData09'), @sync_supported_columns_tblMovementHistory)) WHEN 0 THEN NULL ELSE @UserData09 END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('UserData10'), @sync_supported_columns_tblMovementHistory)) WHEN 0 THEN NULL ELSE @UserData10 END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('TransferDeviation'), @sync_supported_columns_tblMovementHistory)) WHEN 0 THEN NULL ELSE @TransferDeviation END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('TransferPercentDeviation'), @sync_supported_columns_tblMovementHistory)) WHEN 0 THEN NULL ELSE @TransferPercentDeviation END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('DecimalPlacesPercent'), @sync_supported_columns_tblMovementHistory)) WHEN 0 THEN NULL ELSE @DecimalPlacesPercent END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('TransferMode'), @sync_supported_columns_tblMovementHistory)) WHEN 0 THEN NULL ELSE @TransferMode END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('TransferStatus'), @sync_supported_columns_tblMovementHistory)) WHEN 0 THEN NULL ELSE @TransferStatus END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('TransferTarget'), @sync_supported_columns_tblMovementHistory)) WHEN 0 THEN NULL ELSE @TransferTarget END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('TransferTargetUnitsIndex'), @sync_supported_columns_tblMovementHistory)) WHEN 0 THEN NULL ELSE @TransferTargetUnitsIndex END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('TransferLevelTarget'), @sync_supported_columns_tblMovementHistory)) WHEN 0 THEN NULL ELSE @TransferLevelTarget END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('TransferVolumeTarget'), @sync_supported_columns_tblMovementHistory)) WHEN 0 THEN NULL ELSE @TransferVolumeTarget END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('TransferTimeRemaining'), @sync_supported_columns_tblMovementHistory)) WHEN 0 THEN NULL ELSE @TransferTimeRemaining END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('TransferDirection'), @sync_supported_columns_tblMovementHistory)) WHEN 0 THEN NULL ELSE @TransferDirection END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('CommentDateTime'), @sync_supported_columns_tblMovementHistory)) WHEN 0 THEN NULL ELSE @CommentDateTime END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('CommentUserID'), @sync_supported_columns_tblMovementHistory)) WHEN 0 THEN NULL ELSE @CommentUserID END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('Status'), @sync_supported_columns_tblMovementHistory)) WHEN 0 THEN NULL ELSE @Status END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('VolumeWater'), @sync_supported_columns_tblMovementHistory)) WHEN 0 THEN NULL ELSE @VolumeWater END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('LevelProduct'), @sync_supported_columns_tblMovementHistory)) WHEN 0 THEN NULL ELSE @LevelProduct END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('StartDensityProductStandardInAir'), @sync_supported_columns_tblMovementHistory)) WHEN 0 THEN NULL ELSE @StartDensityProductStandardInAir END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('TransferredVolumeWater'), @sync_supported_columns_tblMovementHistory)) WHEN 0 THEN NULL ELSE @TransferredVolumeWater END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('TransferredVolume'), @sync_supported_columns_tblMovementHistory)) WHEN 0 THEN NULL ELSE @TransferredVolume END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('MidnightRecord'), @sync_supported_columns_tblMovementHistory)) WHEN 0 THEN NULL ELSE @MidnightRecord END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('PointGuid'), @sync_supported_columns_tblMovementHistory)) WHEN 0 THEN NULL ELSE @PointGuid END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('RootParentGuid'), @sync_supported_columns_tblMovementHistory)) WHEN 0 THEN NULL ELSE @RootParentGuid END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('RecordSeq'), @sync_supported_columns_tblMovementHistory)) WHEN 0 THEN NULL ELSE @RecordSeq END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('CreatedDate'), @sync_supported_columns_tblMovementHistory)) WHEN 0 THEN NULL ELSE @CreatedDate END),@CreatedBy,@UpdatedDate,@UpdatedBy)
            ;
         SET @sync_row_count = @@rowcount;
    END
    ELSE
    BEGIN
          SET @sync_row_count = 1
    END

    -- If we updated / inserted a record here, go ahead and remove any pending conflict records associated with this ID because this record should contain the most recent data.
    IF (@sync_row_count > 0)
    BEGIN
        SET NOCOUNT ON
        IF EXISTS (SELECT 1 FROM [sync].[tblSyncRecordConflict] WHERE RecordKey = CONVERT(nvarchar(512), @MovementHistoryGuid) AND SyncConflictResolutionStatusIndex IN (0,3))
        BEGIN
            DELETE FROM [sync].[tblSyncRecordConflictToSyncSessionScopeLog] WHERE SyncRecordConflictGuid IN (SELECT SyncRecordConflictGuid FROM [sync].[tblSyncRecordConflict] WHERE RecordKey = CONVERT(nvarchar(512), @MovementHistoryGuid))
            DELETE FROM [sync].[tblSyncRecordConflict] WHERE RecordKey = CONVERT(nvarchar(512), @MovementHistoryGuid)
        END
        SET NOCOUNT OFF
    END

    -- One issue with the MERGE approach is that we don't know if the @@rowcount is zero because of a true conflict now or if it was simply because
    -- the CreatedDate and UpdatedDate qualifiers were not met (in which case we want to simply throw away the update)
    -- In order to determine what took place, we're going to need to perform a query if @@rowcount = 0 to see if it was caused by the additional qualifiers.
    --
    IF (@sync_row_count = 0)
    BEGIN
        IF EXISTS (SELECT 1 FROM [dbo].[tblMovementHistory] WHERE MovementHistoryGuid = @MovementHistoryGuid AND (CreatedDate >= @CreatedDate OR UpdatedDate >= @UpdatedDate))
            SET @sync_row_count = 1;
    END
    
    SET @minValidVersion = 0;   -- This is used to detect Change Tracking cleanup
                                -- If we support this, we should add a column to SynchronizationTable
                                -- that records the MinValidVersion after change tracking information for
                                -- a table gets cleaned up.  I don't think this will be necessary.
    
    IF @minValidVersion > @sync_last_received_anchor 
        RAISERROR(N'(SU)Time between synchronization has exceeded the maximum amount of time for table ''%s'' (MIN: %I64d, LAST: %I64d).  To avoid data corruption and old data, the client must reinitialize its local database with a current refresh from the server.', 16, 3, @sync_table_name, @minValidVersion, @sync_last_received_anchor)
END
